import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"意面代码（Spaghetti Code）","description":"","frontmatter":{},"headers":[],"relativePath":"anti-patterns/spaghetti-code.md","filePath":"anti-patterns/spaghetti-code.md","lastUpdated":0}`),a={name:`anti-patterns/spaghetti-code.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="意面代码-spaghetti-code" tabindex="-1">意面代码（Spaghetti Code） <a class="header-anchor" href="#意面代码-spaghetti-code" aria-label="Permalink to “意面代码（Spaghetti Code）”">​</a></h1><p>意面代码指控制流失去结构：逻辑靠层层跳转、共享变量和隐式顺序串起来，读的时候要靠人肉模拟执行才能知道某一行会不会被执行到。它是 AntiPatterns 里架构类的一条 [S7]，也是新手代码与&quot;先跑起来再说&quot;的代码最常落的形态。</p><h2 id="形态" tabindex="-1">形态 <a class="header-anchor" href="#形态" aria-label="Permalink to “形态”">​</a></h2><ol><li><strong>函数长度失控</strong>：单个函数几百行，中间夹着七八处 <code>return</code> 与若干个跳到函数外的跳出标记。</li><li><strong>状态散落</strong>：判断依赖的变量来自参数、成员字段、全局变量和上一次调用的残留，四者之一变了，行为就变。</li><li><strong>顺序敏感</strong>：必须先调 A 再调 B，调换就出错，而这个顺序只写在某次提交的注释里。</li><li><strong>异常被吞</strong>：<code>catch</code> 块里只有一句注释或一句打日志，错误继续往上冒变成&quot;偶发问题&quot;。</li><li><strong>测试靠点</strong>：自动化用例覆盖不到主流程，回归靠人点界面。</li></ol><h2 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to “代价”">​</a></h2><ul><li>阅读成本远高于编写成本：一个 300 行的函数，新人要看半小时，改 5 行要重新看一遍。</li><li>改动无法局部化：没有一处能被称为&quot;这段逻辑的边界&quot;，回归范围只能按模块估。</li><li>并发下必炸：共享的可变状态多，加锁时只能整函数锁住，吞吐掉下去；漏锁就出竞态。</li><li>排查依赖日志：问题复现要看现场日志，因为代码本身无法静态读出执行路径。</li></ul><h2 id="成因" tabindex="-1">成因 <a class="header-anchor" href="#成因" aria-label="Permalink to “成因”">​</a></h2><ol><li><strong>调试式编写</strong>：先写一半，边跑边加 <code>if</code>，把分支当作调试开关。</li><li><strong>复制式扩展</strong>：从另一处复制一段改几行，两段的边界条件从此各走各的。</li><li><strong>不敢动的重构</strong>：没有测试保护时，改结构的风险高于加分支，于是结构越来越差。</li><li><strong>过早的性能手</strong>：把优化后的内联写法当默认写法，可读性换来的收益没有度量。</li></ol><h2 id="走出来" tabindex="-1">走出来 <a class="header-anchor" href="#走出来" aria-label="Permalink to “走出来”">​</a></h2><p>能一次做完的用手法，动不了的用顺序：</p><ol><li><strong>先立测试</strong>：挑最核心的一条路径，用端到端用例把现有行为钉住（包括那些看起来像 bug 的行为）。没有这一步，后面每一步都是盲改。</li><li><strong>拆长函数</strong>：按&quot;做一件事&quot;切成私有方法，不改任何逻辑，只改结构。切完看参数列表，参数超过三个说明有一组数据该聚成结构体。</li><li><strong>收状态</strong>：把散落的可变变量收进结构体，或收进一个显式的上下文对象，函数只读它。</li><li><strong>把顺序写下来</strong>：多步流程抽成一个方法里的顺序调用，或用<a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链</a>显式表达，谁先谁后在类型上看得见。</li><li><strong>错误路径显式化</strong>：能返回错误就返回错误，不靠全局标志位；跨层的错误统一走一层，取消与中断的语义参考<a href="/hello-design-patterns/behavioral/command">命令模式</a>。</li></ol><p>第 1 步没做完之前不要开始第 2 步，否则重构引入的回归无法区分。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>反面：一段靠共享标志和隐式顺序推进的下单流程。</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E1E4E8;">_ok </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> False</span><span style="color:#818e99;">            # 模块级可变状态，谁都能改</span></span>
<span class="line"><span style="color:#E1E4E8;">_orders </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> []</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> process</span><span style="color:#E1E4E8;">(order):</span></span>
<span class="line"><span style="color:#F97583;">    global</span><span style="color:#E1E4E8;"> _ok</span></span>
<span class="line"><span style="color:#F97583;">    try</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">        reserve(order)                 </span><span style="color:#818e99;"># 占库存</span></span>
<span class="line"><span style="color:#E1E4E8;">        _ok </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> True</span></span>
<span class="line"><span style="color:#F97583;">    except</span><span style="color:#79B8FF;"> Exception</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">        _ok </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> False</span></span>
<span class="line"><span style="color:#F97583;">    if</span><span style="color:#E1E4E8;"> _ok:</span></span>
<span class="line"><span style="color:#E1E4E8;">        charge(order)                  </span><span style="color:#818e99;"># 扣款，失败不回滚库存</span></span>
<span class="line"><span style="color:#E1E4E8;">        _ok </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> True</span></span>
<span class="line"><span style="color:#F97583;">    if</span><span style="color:#E1E4E8;"> _ok:</span></span>
<span class="line"><span style="color:#E1E4E8;">        _orders.append(order)          </span><span style="color:#818e99;"># 落单</span></span>
<span class="line"><span style="color:#E1E4E8;">        notify(order)</span></span>
<span class="line"><span style="color:#818e99;">    # reserve 失败后 charge 的分支不会走，但 charge 失败后 notify 会走：</span></span>
<span class="line"><span style="color:#818e99;">    # 扣款失败也发货，这类问题只能靠线上发现</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>重构后：状态收进一个对象，顺序写在一处，失败分支显式返回。</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#B392F0;">@dataclass</span></span>
<span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> OrderResult</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">    ok: </span><span style="color:#79B8FF;">bool</span></span>
<span class="line"><span style="color:#E1E4E8;">    reason: </span><span style="color:#79B8FF;">str</span><span style="color:#F97583;"> =</span><span style="color:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> OrderProcessor</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#B392F0;"> process</span><span style="color:#E1E4E8;">(self, order) -&gt; OrderResult:</span></span>
<span class="line"><span style="color:#F97583;">        if</span><span style="color:#F97583;"> not</span><span style="color:#79B8FF;"> self</span><span style="color:#E1E4E8;">.inventory.reserve(order):</span></span>
<span class="line"><span style="color:#F97583;">            return</span><span style="color:#E1E4E8;"> OrderResult(</span><span style="color:#79B8FF;">False</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;库存不足&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#F97583;">        if</span><span style="color:#F97583;"> not</span><span style="color:#79B8FF;"> self</span><span style="color:#E1E4E8;">.payments.charge(order):</span></span>
<span class="line"><span style="color:#79B8FF;">            self</span><span style="color:#E1E4E8;">.inventory.release(order)      </span><span style="color:#818e99;"># 失败路径补回占掉的库存</span></span>
<span class="line"><span style="color:#F97583;">            return</span><span style="color:#E1E4E8;"> OrderResult(</span><span style="color:#79B8FF;">False</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;扣款失败&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#79B8FF;">        self</span><span style="color:#E1E4E8;">.store.save(order)</span></span>
<span class="line"><span style="color:#F97583;">        return</span><span style="color:#E1E4E8;"> OrderResult(</span><span style="color:#79B8FF;">True</span><span style="color:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>每一步失败都显式返回，逆操作写在失败处，流程顺序只在一个方法里。测试可以直接对 <code>OrderProcessor</code> 注入假的 <code>inventory</code> 与 <code>payments</code>。</p><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a>：把嵌套的条件分支抽成可替换的算法对象，是拆意面最常用的一刀。</li><li><a href="/hello-design-patterns/behavioral/command">命令模式</a>：把&quot;做什么&quot;封装成对象后，撤销、重试、日志都能挂上去。</li><li><a href="/hello-design-patterns/behavioral/template-method">模板方法模式</a>：多步流程的骨架固定下来，步骤各自可测。</li><li><a href="/hello-design-patterns/anti-patterns/big-ball-of-mud">大泥球</a>：单个函数的失控和整个系统的失控。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S7] Brown 等，《AntiPatterns》，Wiley，1998，Spaghetti Code 条目。</li><li>[S17] SourceMaking 的对应条目，形态段落参照。</li><li>[S6] 《Refactoring》第 2 版，过长函数与重复代码的重构手法。</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};